mapper.select:
SELECT r.id, r.apartment_id, a.name AS apartment_name, r.room_number, r.rent, r.area, r.room_count, r.orientation, r.floor_no, r.publish_status, CASE WHEN EXISTS (SELECT 1 FROM rental_lease l WHERE l.room_id = r.id AND l.is_delete = 0 AND l.status IN (1, 2, 5)) THEN 1 ELSE 0 END AS check_in_status FROM rental_room r JOIN rental_apartment a ON a.id = r.apartment_id AND a.is_delete = 0 WHERE r.is_delete = 0
AND r.apartment_id = #{query.apartmentId}
AND r.room_number LIKE CONCAT('%', #{query.roomNumber}, '%')
AND r.publish_status = #{query.publishStatus}
AND r.rent >= #{query.minRent}
AND r.rent <= #{query.maxRent}
AND NOT EXISTS (SELECT 1 FROM rental_lease l WHERE l.room_id = r.id AND l.is_delete = 0 AND l.status IN (1, 2, 5))
ORDER BY r.id DESC
